import copy
import json

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def get(instance, properties):
    value = execute_tool('editor_toolset.toolsets.object.ObjectTools.get_properties', json.dumps({'instance': instance, 'properties': properties}))['returnValue']
    return json.loads(value)

def set_values(instance, values):
    ok = execute_tool('editor_toolset.toolsets.object.ObjectTools.set_properties', json.dumps({'instance': instance, 'values': json.dumps(values)}))['returnValue']
    if not ok:
        raise RuntimeError('Failed to set properties on ' + instance.get('refPath', 'unknown'))

def run():
    interact_action = '/ExtractionOps/Input/IA_ExtractionInteract.IA_ExtractionInteract'
    imc_path = '/ExtractionOps/Input/IMC_Extraction'
    addons_path = '/ExtractionOps/Input/DA_ExtractionInputAddOns'
    input_action_set_path = '/ExtractionOps/Experiences/DA_ExtractionInputActionSet'
    experience_path = '/ExtractionOps/Experiences/B_ExtractionExperience'

    source_data = get(load('/ShooterExplorer/Input/Mappings/IMC_InventoryTest'), ['defaultKeyMappings'])['defaultKeyMappings']['mappings']
    interact_mapping = None
    for mapping in source_data:
        action = mapping.get('action', {})
        action_path = action.get('refPath', '') if isinstance(action, dict) else str(action)
        if 'IA_Interact' in action_path:
            interact_mapping = copy.deepcopy(mapping)
            break
    if interact_mapping is None:
        raise RuntimeError('ShooterExplorer IA_Interact key mapping was not found')
    interact_mapping['action'] = {'refPath': interact_action}
    interact_mapping['key'] = 'F'

    imc = load(imc_path)
    mapping_data = get(imc, ['defaultKeyMappings'])['defaultKeyMappings']
    mappings = mapping_data['mappings']
    conflicting_key = [mapping for mapping in mappings if str(mapping.get('key', '')) == interact_mapping['key']]
    if conflicting_key:
        raise RuntimeError(interact_mapping['key'] + ' is already mapped in IMC_Extraction')
    if not any('IA_ExtractionInteract' in str(mapping.get('action', '')) for mapping in mappings):
        set_values(imc, {'defaultKeyMappings': {'mappings': mappings + [interact_mapping]}})

    addons = load(addons_path)
    ability_actions = get(addons, ['abilityInputActions'])['abilityInputActions']
    if not any(action.get('inputTag', {}).get('tagName') == 'InputTag.Ability.Interact' for action in ability_actions):
        set_values(addons, {'abilityInputActions': ability_actions + [{
            'inputAction': {'refPath': interact_action},
            'inputTag': {'tagName': 'InputTag.Ability.Interact'}
        }]})

    set_values({'refPath': '/ExtractionOps/Experiences/DA_ExtractionInputActionSet.DA_ExtractionInputActionSet:GameFeatureAction_AddInputBinding_0'}, {
        'inputConfigs': ['/ExtractionOps/Input/DA_ExtractionInputAddOns.DA_ExtractionInputAddOns']
    })
    set_values({'refPath': '/ExtractionOps/Experiences/DA_ExtractionInputActionSet.DA_ExtractionInputActionSet:GameFeatureAction_AddInputContextMapping_0'}, {
        'inputMappings': [{
            'inputMapping': '/ExtractionOps/Input/IMC_Extraction.IMC_Extraction',
            'priority': 0,
            'bRegisterWithSettings': True
        }]
    })

    experience = load(experience_path)
    set_values(experience, {'actionSets': []})
    set_values(experience, {'actionSets': [
        {'refPath': '/ExtractionOps/Experiences/DA_ExtractionInputActionSet.DA_ExtractionInputActionSet'},
        {'refPath': '/ShooterCore/Experiences/LAS_ShooterGame_StandardComponents.LAS_ShooterGame_StandardComponents'},
        {'refPath': '/ExtractionOps/Experiences/DA_ExtractionActionSet.DA_ExtractionActionSet'}
    ]})

    execute_tool('editor_toolset.toolsets.blueprint.BlueprintTools.compile_blueprint', json.dumps({'blueprint': load(experience_path), 'warnings_as_errors': True}))
    paths = [imc_path, addons_path, input_action_set_path, experience_path, '/ExtractionOps/Input/IA_ExtractionInteract']
    if not execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': paths}))['returnValue']:
        raise RuntimeError('Failed to save configured Week 3 input assets')
    return {'configured': paths, 'interactKey': interact_mapping['key'], 'interactTag': 'InputTag.Ability.Interact'}
